        h.kind = static_cast<std::uint8_t>(2);
        if (auto e = h.write(w); !e) return gmp::fail(e.error());
        [[maybe_unused]] const std::size_t body_at = w.position();
        if (auto e = m.write(w); !e) return gmp::fail(e.error());
